#!/bin/bash
# =============================================================================
# ISRM Insight Hub — Self-contained patch applier (Oct 2026, Round 1-4)
# =============================================================================
# Цей скрипт містить УСІ 4 патчі вбудованими як base64-строки.
# Не потребує жодних зовнішніх файлів — просто збережіть цей файл на Mac
# і запустіть: bash apply-isrm-patches-standalone.sh
#
# Безпечно: перевіряє гілку, чистоту робочого дерева, дає опції при конфліктах.
# =============================================================================

set -u

# --- Кольори ---
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m'

echo -e "${GREEN}"
echo "╔══════════════════════════════════════════════════════════════╗"
echo "║  ISRM Insight Hub — Self-contained Patch Applier (Oct 2026)  ║"
echo "╚══════════════════════════════════════════════════════════════╝"
echo -e "${NC}"

# --- Конфігурація ---
REPO_DIR="${REPO_DIR:-/Users/alexzvo/.copilot/repos/isrm-insight-hub}"
BRANCH="isrm-partner-ranges-v1"
REMOTE="origin"

# --- Опції ---
DRY_RUN=0
NO_PUSH=0
RESET_FIRST=0

for arg in "$@"; do
  case "$arg" in
    --dry-run)     DRY_RUN=1 ;;
    --no-push)     NO_PUSH=1 ;;
    --reset-first) RESET_FIRST=1 ;;
    --help|-h)
      echo "Використання: bash $0 [--dry-run] [--no-push] [--reset-first]"
      echo "  --dry-run      Тільки перевірка без змін"
      echo "  --no-push      Застосувати без push"
      echo "  --reset-first  Спочатку git reset --hard origin"
      exit 0
      ;;
  esac
done

# --- [1/8] Перевірка директорії проєкту ---
echo -e "${BLUE}[1/8] Перевірка директорії...${NC}"
if [ ! -d "${REPO_DIR}/.git" ]; then
  echo -e "${RED}Помилка: ${REPO_DIR} не знайдено або не є git-репо${NC}"
  echo "Якщо шлях інший: REPO_DIR=/ваш/шлях bash $0"
  exit 1
fi
echo -e "${GREEN}✓ ${REPO_DIR}${NC}"
echo ""

# --- [2/8] Перевірка інструментів ---
echo -e "${BLUE}[2/8] Перевірка base64 + git...${NC}"
command -v base64 >/dev/null 2>&1 || { echo -e "${RED}base64 не знайдено${NC}"; exit 1; }
command -v git >/dev/null 2>&1 || { echo -e "${RED}git не знайдено${NC}"; exit 1; }
echo -e "${GREEN}✓ base64 + git доступні${NC}"
echo ""

# --- [3/8] Перехід у репо + checkout гілки ---
echo -e "${BLUE}[3/8] Checkout ${BRANCH}...${NC}"
cd "${REPO_DIR}"
CURRENT=$(git rev-parse --abbrev-ref HEAD)
if [ "${CURRENT}" != "${BRANCH}" ]; then
  git checkout "${BRANCH}" || { echo -e "${RED}Не вдалося перемкнутися${NC}"; exit 1; }
fi
echo -e "${GREEN}✓ На гілці: ${BRANCH}${NC}"
echo ""

# --- [4/8] Fetch ---
echo -e "${BLUE}[4/8] git fetch origin...${NC}"
git fetch "${REMOTE}" 2>&1 | sed 's/^/  /'
echo -e "${GREEN}✓ Fetch завершено${NC}"
echo ""

# --- [5/8] Опціональний reset ---
if [ $RESET_FIRST -eq 1 ]; then
  echo -e "${BLUE}[5/8] Reset до origin/${BRANCH}...${NC}"
  read -p "Увага: це знищить локальні зміни. Продовжити? (y/N): " c
  if [ "$c" = "y" ] || [ "$c" = "Y" ]; then
    git reset --hard "${REMOTE}/${BRANCH}"
    echo -e "${GREEN}✓ Reset${NC}"
  fi
  echo ""
fi

# --- [6/8] Перевірка робочого дерева ---
echo -e "${BLUE}[6/8] Перевірка робочого дерева...${NC}"
if [ -n "$(git status --porcelain)" ]; then
  echo -e "${YELLOW}  Незакомічені зміни:${NC}"
  git status --short | head -15 | sed 's/^/    /'
  echo ""
  echo "  Опції:"
  echo "    1) git stash (безпечно, повернете після)"
  echo "    2) git add -A && git commit (закомітити WIP)"
  echo "    3) git checkout -- . (скинути, УВАГА: втратите)"
  echo "    4) Перервати"
  read -p "  Вибір [1/2/3/4] (за замовч 4): " ch
  ch=${ch:-4}
  case $ch in
    1) git stash; echo -e "${GREEN}  ✓ Stash${NC}"; echo -e "${YELLOW}  Після: git stash pop${NC}" ;;
    2) git add -A; git commit -m "WIP local changes (auto)" ;;
    3) read -p "  Точно? (y/N): " cf; [ "$cf" = "y" ] && git checkout -- . || { echo "Скасовано"; exit 1; } ;;
    *) echo -e "${RED}  Перервано${NC}"; exit 1 ;;
  esac
else
  echo -e "${GREEN}  ✓ Робоче дерево чисте${NC}"
fi
echo ""

# --- [7/8] Розпакування та застосування патчів ---
echo -e "${BLUE}[7/8] Розпакування патчів з base64...${NC}"
TMPDIR=$(mktemp -d)
trap "rm -rf ${TMPDIR}" EXIT

# 4 патчі в base64, розділені маркерами
PATCH_NAMES=(
  "0001-feat-proposal-scope-partner-graph-apply-pinpoint-rep.patch"
  "0002-fix-access-partner-move-password-to-cabinet-UnlockDi.patch"
  "0003-feat-graph-scope-MVP-lock-bug-16-fix-shadow-edges-st.patch"
  "0004-feat-ds-graph-scope-apply-DS-EL-REFUGIO-Sand-Teal-re.patch"
)

# Base64 блок для патчу 1 — окремий маркер
B64_PATCH1_END_MARKER="__PATCH1_END_b9d3a1f7__"
B64_PATCH2_END_MARKER="__PATCH2_END_c7e5b2a8__"
B64_PATCH3_END_MARKER="__PATCH3_END_d1f9c6b3__"
B64_PATCH4_END_MARKER="__PATCH4_END_e8a4d7c9__"

# --- PATCH 1: 0001-feat-proposal-scope-partner-graph-apply-pinpoint-rep.patch ---
# Базові дані патчу будуть вставлені нижче між маркерами BEGIN_PATCH1 і END_PATCH1
echo -e "${BLUE}  Розпакування патчу 1/4...${NC}"
if ! sed -n '/^__BEGIN_PATCH1__$/,/^__END_PATCH1__$/p' "$0" | sed '1d;$d' | base64 -d > "${TMPDIR}/${PATCH_NAMES[0]}" 2>/dev/null; then
  echo -e "${RED}  ✗ Не вдалося розпакувати патч 1${NC}"
  exit 1
fi
SIZE1=$(wc -c < "${TMPDIR}/${PATCH_NAMES[0]}")
echo -e "${GREEN}  ✓ Патч 1: ${SIZE1} байт${NC}"

# --- PATCH 2: 0002-fix-access-partner-move-password-to-cabinet-UnlockDi.patch ---
echo -e "${BLUE}  Розпакування патчу 2/4...${NC}"
if ! sed -n '/^__BEGIN_PATCH2__$/,/^__END_PATCH2__$/p' "$0" | sed '1d;$d' | base64 -d > "${TMPDIR}/${PATCH_NAMES[1]}" 2>/dev/null; then
  echo -e "${RED}  ✗ Не вдалося розпакувати патч 2${NC}"
  exit 1
fi
SIZE2=$(wc -c < "${TMPDIR}/${PATCH_NAMES[1]}")
echo -e "${GREEN}  ✓ Патч 2: ${SIZE2} байт${NC}"

# --- PATCH 3: 0003-feat-graph-scope-MVP-lock-bug-16-fix-shadow-edges-st.patch ---
echo -e "${BLUE}  Розпакування патчу 3/4...${NC}"
if ! sed -n '/^__BEGIN_PATCH3__$/,/^__END_PATCH3__$/p' "$0" | sed '1d;$d' | base64 -d > "${TMPDIR}/${PATCH_NAMES[2]}" 2>/dev/null; then
  echo -e "${RED}  ✗ Не вдалося розпакувати патч 3${NC}"
  exit 1
fi
SIZE3=$(wc -c < "${TMPDIR}/${PATCH_NAMES[2]}")
echo -e "${GREEN}  ✓ Патч 3: ${SIZE3} байт${NC}"

# --- PATCH 4: 0004-feat-ds-graph-scope-apply-DS-EL-REFUGIO-Sand-Teal-re.patch ---
echo -e "${BLUE}  Розпакування патчу 4/4...${NC}"
if ! sed -n '/^__BEGIN_PATCH4__$/,/^__END_PATCH4__$/p' "$0" | sed '1d;$d' | base64 -d > "${TMPDIR}/${PATCH_NAMES[3]}" 2>/dev/null; then
  echo -e "${RED}  ✗ Не вдалося розпакувати патч 4${NC}"
  exit 1
fi
SIZE4=$(wc -c < "${TMPDIR}/${PATCH_NAMES[3]}")
echo -e "${GREEN}  ✓ Патч 4: ${SIZE4} байт${NC}"
echo ""

if [ $DRY_RUN -eq 1 ]; then
  echo -e "${YELLOW}Dry-run: перевірка чи патчі пройдуть чисто...${NC}"
  for i in 0 1 2 3; do
    n=$((i + 1))
    if git apply --check "${TMPDIR}/${PATCH_NAMES[$i]}" 2>&1; then
      echo -e "${GREEN}  ✓ Патч ${n} пройде чисто${NC}"
    else
      echo -e "${YELLOW}  ⚠ Патч ${n} має конфлікти (це нормально якщо попередні ще не застосовано)${NC}"
    fi
  done
  echo ""
  echo -e "${GREEN}Dry-run завершено. Запустіть без --dry-run для застосування.${NC}"
  exit 0
fi

# --- Застосування ---
echo -e "${BLUE}Застосування патчів через git am --3way...${NC}"
APPLIED=0
for i in 0 1 2 3; do
  n=$((i + 1))
  echo ""
  echo -e "${BLUE}  [${n}/4] ${PATCH_NAMES[$i]}${NC}"
  if git am --3way "${TMPDIR}/${PATCH_NAMES[$i]}" 2>&1 | sed 's/^/    /'; then
    if git am --show-current-patch >/dev/null 2>&1; then
      # git am might be in a conflict state, check
      :
    fi
    if [ -z "$(git status --porcelain 2>/dev/null | grep -E '^(UU|AA|DD|AU|UD|UA|DU)')" ]; then
      echo -e "${GREEN}    ✓ Патч ${n} застосовано${NC}"
      APPLIED=$((APPLIED + 1))
    else
      echo -e "${RED}    ✗ Конфлікт у патчі ${n}!${NC}"
      git status --short | head -10 | sed 's/^/      /'
      echo ""
      echo "    Опції:"
      echo "      1) Розв'язати вручну: git add <files> && git am --continue"
      echo "      2) Пропустити: git am --skip"
      echo "      3) Відмінити все: git am --abort"
      read -p "    [1/2/3] (за замовч 3): " cc
      cc=${cc:-3}
      case $cc in
        1) echo -e "${YELLOW}    Розв'яжіть конфлікт, потім: git add <files> && git am --continue${NC}"; exit 1 ;;
        2) git am --skip; echo -e "${YELLOW}    Пропущено${NC}" ;;
        3) git am --abort; echo -e "${RED}    Усі відмінено${NC}"; exit 1 ;;
      esac
    fi
  else
    echo -e "${RED}    ✗ Помилка у патчі ${n}${NC}"
    git status --short | head -10 | sed 's/^/      /'
    echo "    Опції: 1) розв'язати 2) skip 3) abort"
    read -p "    [1/2/3] (за замовч 3): " cc
    cc=${cc:-3}
    case $cc in
      1) exit 1 ;;
      2) git am --skip 2>/dev/null || true ;;
      3) git am --abort 2>/dev/null || true; exit 1 ;;
    esac
  fi
done

echo ""
echo -e "${GREEN}✓ Застосовано ${APPLIED} з 4 патчів${NC}"
echo ""

# --- [8/8] Push ---
echo -e "${BLUE}[8/8] Статус + push...${NC}"
git log --oneline -6 | sed 's/^/  /'
echo ""

if [ $NO_PUSH -eq 1 ]; then
  echo -e "${YELLOW}Push пропущено (--no-push)${NC}"
  echo "  git push origin ${BRANCH}"
  exit 0
fi

read -p "Push у ${REMOTE}/${BRANCH}? (y/N): " pc
if [ "$pc" = "y" ] || [ "$pc" = "Y" ]; then
  echo -e "${BLUE}Push...${NC}"
  if git push origin "${BRANCH}" 2>&1 | sed 's/^/  /'; then
    echo -e "${GREEN}✓ Push успішний!${NC}"
    echo ""
    echo "  GitHub Actions: https://github.com/AlexezavGit/isrm-insight-hub/actions"
    echo "  Live:           https://isrm.pages.dev"
    echo ""
    echo "  Перевірити на сайті:"
    echo "    • Sign in на home graph: пароль isrm-cabinet-2026-zv"
    echo "    • /proposal — H1 'Trusted Practice', inset заголовки"
    echo "    • /scope — 'Цикл залучення у поле впливу' + MHPSS †"
    echo "    • Search кнопка перемикає expert/service режим"
    echo "    • Dashboard показує 'X сервісів / 8'"
    echo "    • Timeline — анімовані pins"
  else
    echo -e "${RED}✗ Push не вдався${NC}"
    echo "  Можливо потрібне налаштування gh auth або PAT"
    exit 1
  fi
else
  echo -e "${YELLOW}Push пропущено. Зробіть вручну: git push origin ${BRANCH}${NC}"
fi

echo ""
echo -e "${GREEN}=== Готово ===${NC}"

exit 0

# =============================================================================
# Base64-блоки патчів (нижче текст скрипта).
# Format: __BEGIN_PATCHN__ <base64> __END_PATCHN__
# Скрипт використовує sed для витягнення між маркерами + base64 -d для декодування
# =============================================================================

